import json,html
from pathlib import Path
P=Path(__file__).parent;R=json.loads((P/'results.json').read_text());I=json.loads((P/'inputs.json').read_text());W=R['wholeline']
def esc(x):return html.escape(str(x))
def n(x,dp=0):return f'{x:,.{dp}f}'.replace(',',' ').replace('.',',')
def pct(x):return n(x*100,2)+'%'
def cell(x):return '<td>'+str(x)+'</td>'
def table(headers,rows):return '<div class="scroll"><table><thead><tr>'+''.join('<th>'+esc(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(cell(v) for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def whole(name='all_modelled_orders',period='all_q3'):return next(x for x in W['subsets'] if x['subset']==name and x['period']==period)
wl=whole()['totals'];main=R['main8'];strict=R['cohorts8']['strict_fully_priced_matched_starter']
body='<p class="eyebrow">ТЕПЛО · ЧЕРНИКОВА · 21 ОКТЯБРЯ 2026</p><h1>Улучшенные роллы: хватает ли 33%?</h1><p class="lead">Если меняем только восемь проверенных рецептур, вся линия остаётся ниже 33% в обоих сценариях. Сама восьмёрка при действующих акциях превышает ориентир; при облегчённых укладывается.</p>'
body+='<div class="cards">'
for title,cur,light in [('Восемь улучшенных',main['current']['trial_fc'],main['lighter']['trial_fc']),('Вся линия: улучшены только восемь',wl['trial_fc_lower_bound_current'],wl['trial_fc_lower_bound_lighter'])]:
 body+='<section class="card"><h2>'+title+'</h2><div class="pair"><div><small>Действующие акции</small><strong>'+pct(cur)+'</strong></div><div><small>Облегчённые</small><strong>'+pct(light)+'</strong></div></div></section>'
body+='</div><p class="note">Это сценарий на составе заказов июля–сентября при ценах меню на 21 октября. Показатели всей линии приблизительные: 50 г тунцовой стружки не оценены; вода отдельно не оценивалась. Новые рецептуры остальных роллов ещё не проверены.</p>'
body+='<h2>Каждый из восьми</h2><p>Цена — отдельная продажа на витрине. FC — с учётом продаж в сетах, скидок, списанных бонусов, подарочных порций и упаковки, уже включённой в техкарты сетов. Стоимость порции — чистая рецептура из видео, без добавочной сетовой упаковки.</p>'
body+=table(['Ролл','Цена меню, ₽','Сырьё было → стало, ₽','FC: действующие','FC: облегчённые'],[[esc(r['name']),n(r['retail_price_rub']),n(r['baseline_unit_food_rub'],2)+' → '+n(r['trial_unit_food_rub'],2),'<b class="'+('over' if r['current']['trial_fc']>.33 else 'ok')+'">'+pct(r['current']['trial_fc'])+'</b>','<b class="'+('over' if r['lighter']['trial_fc']>.33 else 'ok')+'">'+pct(r['lighter']['trial_fc'])+'</b>'] for r in R['rows']])
body+='<p class="callout"><b>Лава с креветкой требует отдельной проработки.</b> Даже вне сетов и до скидок: 123,79 / 325 = 38,09%. Бюджет сырья при 33% и полной цене — 107,25 ₽, на 16,54 ₽ меньше пробной рецептуры. Это не требование урезать начинку: нужно выбрать сочетание состава, цены и роли в сетах. 33% — ориентир всей линии, отдельные позиции могут быть выше.</p>'
body+='<h2>Четыре сочетания рецептур и акций</h2>'
body+=table(['Рецептуры','Восемь: действующие','Восемь: облегчённые','Вся линия: действующие','Вся линия: облегчённые'],[['Нынешние',pct(main['current']['baseline_fc']),pct(main['lighter']['baseline_fc']),pct(wl['baseline_fc_lower_bound_current']),pct(wl['baseline_fc_lower_bound_lighter'])],['Изменены только восемь',pct(main['current']['trial_fc']),pct(main['lighter']['trial_fc']),pct(wl['trial_fc_lower_bound_current']),pct(wl['trial_fc_lower_bound_lighter'])]])
body+='<h2>Сколько остаётся до 33% всей линии</h2>'
body+=table(['На тот же квартальный состав','Действующие','Облегчённые'],[['Распределённая оплата роллов, ₽',n(wl['rollline_net_current']),n(wl['rollline_net_lighter'])],['Рецептуры и упаковка из карт, ₽',n(wl['trial_food_known_lower_bound_current']),n(wl['trial_food_known_lower_bound_lighter'])],['Остаток бюджета сырья до 33%, ₽',n(wl['remaining_material_budget_at33_before_unpriced_goods_current']),n(wl['remaining_material_budget_at33_before_unpriced_goods_lighter'])],['В среднем на месяц, ₽',n(wl['remaining_material_budget_at33_before_unpriced_goods_current']/3),n(wl['remaining_material_budget_at33_before_unpriced_goods_lighter']/3)]])
body+='<p>Из остатка ещё нужно вычесть стоимость 50 г тунцовой стружки. Это бюджет дальнейшего удорожания рецептур при сохранённом составе продаж, а не дополнительная чистая прибыль. Новое оборудование, труд, потери, доставка, комиссии и налоги оцениваются в полной модели отдельно.</p>'
body+='<h2>Проверка по месяцам</h2>'
monthnames={'2026-07':'Июль','2026-08':'Август','2026-09':'Сентябрь'}
body+=table(['Месяц','Восемь: действующие','Восемь: облегчённые','Вся линия: действующие','Вся линия: облегчённые'],[[monthnames[m],pct(v['current']['trial_fc']),pct(v['lighter']['trial_fc']),pct(whole(period=m)['totals']['trial_fc_lower_bound_current']),pct(whole(period=m)['totals']['trial_fc_lower_bound_lighter'])] for m,v in R['months8'].items()])
body+='<h2>Как изменены акции в расчёте</h2><ul><li>Убраны подарочная шкала, самовывоз 10% и новые реферальные выгоды. Первый заказ — 15%, день рождения сохранён.</li><li>Лояльность 5/7/10% сохранена; списание до 50%, одна денежная выгода. Акционные наборы и все подтверждённые пицца-комбо исключены из списания. Ранее заработанные баллы не аннулируются.</li><li>Удвоение сопоставлено при том же физическом количестве еды и нормализованной цене за порцию. Его отмена не создаёт искусственную экономию продуктов.</li></ul>'
body+='<h2>Насколько устойчив результат</h2>'
body+=table(['Выборка','Заказов с восемью роллами','FC8: действующие','FC8: облегчённые'],[[title,n(R['cohorts8'][key]['orders_with_target8']),pct(R['cohorts8'][key]['current']['trial_fc']),pct(R['cohorts8'][key]['lighter']['trial_fc'])] for key,title in [('all_modelled_orders','Полная условная модель'),('starter_matched','Сопоставлены со Starter'),('fully_current_priced_orders','Все товары корзины с текущей ценой'),('strict_fully_priced_matched_starter','Строгая проверенная подвыборка')]])
body+='<p>Всего 5 507 iiko-заказов; получены 4 202 карточки Starter, связаны 4 198. Строгая выборка — 2 102 заказа, около 53% порций и выручки восьмёрки. В ней исключены неизвестные цены корзины и несходящиеся чеки. В полной модели неизвестные текущие цены прочих товаров сохранены по исторической цене как явное допущение; у каналов вне Starter сохранена прежняя скидочная нагрузка.</p><p>Для двух сетовых компонентов без самостоятельной цены используются отмеченные веса. Альтернативное равномерное распределение даёт примерно 34,60% / 30,91% по восьмёрке; основной вывод сохраняется. Чувствительность к сохранению доли бонусов вместо их прежних рублей — менее 0,004 процентного пункта. Правила выбора акции и будущая реакция гостей не проверялись запуском.</p>'
body+='<details><summary>Роль сетов: все 18 родителей</summary><p>Для смешанных наборов показана только ролловая часть. Пицца и её выручка не добавлены к линии роллов. Долю смешанной ветки фиксируем по её наблюдённому историческому сырью в каждом чеке; между вариантами рецептур она не меняется. Подарочный сет с нулевой оплатой имеет сырьё, но не определённый процент FC сам по себе.</p>'
srows=[x for x in W['set_level'] if x['subset']=='all_modelled_orders' and x['period']=='all_q3']
body+=table(['Сет / родитель','FC ролловой части: действующие','FC ролловой части: облегчённые','Сырьё текущего сценария, ₽'],[[esc(s['root_name']),pct(s['totals']['trial_fc_current']) if s['totals']['trial_fc_current'] is not None else 'Подарок; оплаты нет',pct(s['totals']['trial_fc_lighter']) if s['totals']['trial_fc_lighter'] is not None else 'Нет оплаты',n(s['totals']['trial_food_known_lower_bound_current'])] for s in srows])+'</details>'
body+='<h2>Что проверять дальше</h2><p>Проработать оставшиеся позиции и добавить их изменения к фактическому рублёвому бюджету сырья. Отдельно проверить вкус, стабильность порции и доставку. Только после выбора всего предложения заменить ориентир FC в модели прибыли; этот расчёт не пересчитывает объём заказов для 500 тысяч и не доказывает спрос или мощность кухни.</p><footer><a href="https://teplofood.ru/">Цены витрины «Тепло»</a> · <a href="results.json">Числа</a> · <a href="inputs.json">Безличные входы</a> · <a href="source-manifest.json">Источники</a> · <a href="method.md">Метод</a> · <a href="validation.json">Сверки</a><p>Сырьё и карты — read-only iiko, цены и акции — Starter/витрина, срез 21.10.2026. Технический GUID витрины не получен: цены сопоставлены вручную по названиям и подтверждённым размерам. Невзвешенные нори, кляр и сухари — условно по прежним картам. Рецептуры, цены и акции в производстве не изменялись.</p></footer>'
style='''*{box-sizing:border-box}body{margin:0;background:#f4f3ef;color:#202923;font:16px/1.65 system-ui,-apple-system,BlinkMacSystemFont,sans-serif}main{max-width:1240px;margin:auto;padding:48px 36px 72px}h1{font-size:clamp(32px,5vw,52px);line-height:1.1;letter-spacing:-1.6px;margin:14px 0 24px;max-width:900px}h2{line-height:1.25;margin:38px 0 14px;font-size:25px}.lead{font-size:21px;max-width:940px}.eyebrow{letter-spacing:2px;color:#5a6a60;font-size:12px;font-weight:700}.cards{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:32px 0 20px}.card{background:white;border:1px solid #dce1d9;border-radius:18px;padding:24px}.card h2{margin:0 0 24px;font-size:19px}.pair{display:flex;gap:32px;justify-content:space-between}.pair strong{display:block;font-size:36px;letter-spacing:-1px}.pair small{color:#667469}.note,footer{color:#647067;font-size:13px}.scroll{overflow-x:auto;border:1px solid #dae0d8;border-radius:12px;margin:20px 0;background:white}table{border-collapse:collapse;width:100%;min-width:650px;font-variant-numeric:tabular-nums}th,td{padding:14px 16px;border-bottom:1px solid #e7ebe5;text-align:right;white-space:nowrap}th{font-size:13px;color:#54645a;background:#edf0e9}td:first-child,th:first-child{text-align:left;white-space:normal;min-width:200px}tr:last-child td{border:0}.over{color:#ad5831}.ok{color:#287254}.callout{border-left:4px solid #b98d4b;padding:18px 22px;background:#fff9ed;border-radius:0 12px 12px 0}details{border:1px solid #d6dfd5;border-radius:12px;padding:18px;margin:32px 0}summary{cursor:pointer;font-weight:650}footer{margin-top:48px;padding-top:24px;border-top:1px solid #d3dcd3}a{color:#267254}li{margin:10px 0}@media(max-width:760px){main{padding:28px 18px 44px}.cards{grid-template-columns:1fr}.pair strong{font-size:32px}.lead{font-size:18px}td,th{padding:12px}}@media print{body{background:white}main{padding:12px}details{display:block}.scroll{overflow:visible}table{font-size:10px;min-width:0}td,th{white-space:normal;padding:7px}.cards{break-inside:avoid}}'''
